package io.github.ningpp.compat;

/**
 * Replacement for System.WeakReference and System.WeakReference&lt;T&gt;
 * (generated by CSharpToJava converter). Generic so that C# WeakReference&lt;T&gt;
 * usages compile; raw (non-generic) usages keep working via T = Object erasure.
 */
public class WeakReference<T> {
    private java.lang.ref.WeakReference<Object> ref;

    public WeakReference(T target) {
        this.ref = new java.lang.ref.WeakReference<>(target);
    }

    public WeakReference(T target, boolean trackResurrection) {
        // Java's WeakReference has no resurrection tracking; accepted for API parity.
        this(target);
    }

    public boolean getIsAlive() {
        return ref.get() != null;
    }

    @SuppressWarnings("unchecked")
    public T getTarget() {
        return (T) ref.get();
    }

    public void setTarget(T value) {
        this.ref = new java.lang.ref.WeakReference<>(value);
    }

    /** C# WeakReference&lt;T&gt;.TryGetTarget(out T target) */
    @SuppressWarnings("unchecked")
    public boolean tryGetTarget(ObjectHolder<T> target) {
        Object value = ref.get();
        if (value != null) {
            target.value = (T) value;
            return true;
        }
        return false;
    }
}
